R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p; cat /proc/loadavg
w=sb_mask_carry; mkdir -p $R/$w/in/v2; echo  | base64 -d | tar xzf - -C $R/$w/in/v2; (cd $R/$w/in/v2 && sha256sum -c --quiet SHA256SUMS && echo carry v2 OK)
mv $R/$w/cursor.log $R/$w/cursor_stopped_1006Z.log 2>/dev/null; echo  | base64 -d > $R/$w/PROMPT.md
mkdir -p $R/sb_mask_phrase/in/v3; echo  | base64 -d | tar xzf - -C $R/sb_mask_phrase/in/v3
mkdir -p $R/sb_cachefix; cp $R/sb_cursor_probe/AGENTS.md $R/sb_cachefix/AGENTS.md; echo  | base64 -d > $R/sb_cachefix/PROMPT.md
for w in sb_mask_carry sb_cachefix; do cd $R/$w && tmux new-session -d -s $w "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"; sleep 3; done
tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo; tail -2 $R/sb_queue/codexq.log
for t in sb_ktfix sb_rkfam sb_mask_phrase sb_rlfix3; do echo "== $t: $(head -c 300 $R/$t/STATUS.md 2>/dev/null)"; done
